function checkPng(bytes) {
  if (!bytes || bytes.length < 24) throw Error("Screenshot PNG header is incomplete");
  const sig = [137, 80, 78, 71, 13, 10, 26, 10];
  if (
    sig.some((x, i) => bytes[i] !== x) ||
    bytes[8] !== 0 ||
    bytes[9] !== 0 ||
    bytes[10] !== 0 ||
    bytes[11] !== 13 ||
    String.fromCharCode(...bytes.slice(12, 16)) !== "IHDR"
  )
    throw Error("Screenshot is not a PNG with an IHDR header");
  const u = (i) => bytes[i] * 16777216 + bytes[i + 1] * 65536 + bytes[i + 2] * 256 + bytes[i + 3],
    width = u(16),
    height = u(20);
  if (width !== 1024 || height < 1 || height >= 20000)
    throw Error("Screenshot dimensions may indicate truncation or scaling");
  return true;
}

const url = $("Check the Screenshotbase URL").first().json.url;
if (!validUrl(url) || !/^https:\/\/(?:cache|cdn)\.screenshotbase\.com(?:[/?#]|$)/i.test(url))
  throw Error("Invalid Screenshotbase CDN URL");
const bytes = await this.helpers.getBinaryDataBuffer(0, "data");
checkPng(bytes);
return [{ json: { photo: url } }];
